def schedule():
    out = []
    for i, p in enumerate(P):
        d = DAYS[i // 3]
        p = dict(p); p['date'], p['day'], p['theme_day'] = d; p['time'] = TIMES[i % 3]
        p['pillar'] = {'09:00': 'La verdad incómoda', '14:00': 'Cómo se hace', '18:00': 'Prueba y acción'}[p['time']]
        out.append(p)
    return out
